def F(x, y, z, a, b, c):
    return abs(x + y - a - b) + abs(y + z - b - c) + abs(z + x - c - a)

# Define three query vectors
queries = [
    (1, 0, 0),  # Q1
    (5, 5, 5),  # Q2
    (9, 0, 0)   # Q3
]

# Store results: (Q1_val, Q2_val, Q3_val) -> list of (x, y, z) triplets
collision_map = {}

# Iterate through all possible input triplets (x, y, z)
