            results = []
            for q_index, (a, b, c) in enumerate(queries):
                val = F(x, y, z, a, b, c)
                results.append(val)

            key = tuple(results)
            if key not in collision_map:
                collision_map[key] = []
            collision_map[key].append((x, y, z))

# Check for collisions (where a key maps to more than one triplet)
collisions = {key: triplets for key, triplets in collision_map.items() if len(triplets) > 1}

